CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'passenger', phone VARCHAR(30), created_at DATETIME NOT NULL);
CREATE TABLE bus_routes (id INT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, origin VARCHAR(120) NOT NULL, destination VARCHAR(120) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE pass_types (id INT AUTO_INCREMENT PRIMARY KEY, category VARCHAR(30) NOT NULL, duration VARCHAR(30) NOT NULL, duration_days INT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE KEY uq_category_duration(category,duration));
CREATE TABLE fare_rules (id INT AUTO_INCREMENT PRIMARY KEY, route_id INT NOT NULL, pass_type_id INT NOT NULL, amount DECIMAL(10,2) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE KEY uq_route_type(route_id,pass_type_id), FOREIGN KEY(route_id) REFERENCES bus_routes(id), FOREIGN KEY(pass_type_id) REFERENCES pass_types(id));
CREATE TABLE pass_applications (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, route_id INT NOT NULL, pass_type_id INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'Pending', review_reason VARCHAR(500), created_at DATETIME NOT NULL, reviewed_at DATETIME, INDEX ix_application_user(user_id), INDEX ix_application_status(status), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(route_id) REFERENCES bus_routes(id), FOREIGN KEY(pass_type_id) REFERENCES pass_types(id));
CREATE TABLE bus_passes (id INT AUTO_INCREMENT PRIMARY KEY, application_id INT NOT NULL UNIQUE, user_id INT NOT NULL, route_id INT NOT NULL, pass_type_id INT NOT NULL, pass_number VARCHAR(40) NOT NULL UNIQUE, verification_token VARCHAR(64) NOT NULL UNIQUE, issued_at DATE NOT NULL, expires_at DATE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'Active', INDEX ix_pass_user(user_id), INDEX ix_pass_number(pass_number), INDEX ix_pass_expiry(expires_at), INDEX ix_pass_status(status), FOREIGN KEY(application_id) REFERENCES pass_applications(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(route_id) REFERENCES bus_routes(id), FOREIGN KEY(pass_type_id) REFERENCES pass_types(id));
CREATE TABLE payments (id INT AUTO_INCREMENT PRIMARY KEY, application_id INT NOT NULL, user_id INT NOT NULL, transaction_ref VARCHAR(50) NOT NULL UNIQUE, amount DECIMAL(10,2) NOT NULL, status VARCHAR(20) NOT NULL, created_at DATETIME NOT NULL, INDEX ix_payment_application(application_id), FOREIGN KEY(application_id) REFERENCES pass_applications(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE verification_logs (id INT AUTO_INCREMENT PRIMARY KEY, pass_id INT NULL, verifier_id INT NOT NULL, result VARCHAR(30) NOT NULL, checked_at DATETIME NOT NULL, FOREIGN KEY(pass_id) REFERENCES bus_passes(id), FOREIGN KEY(verifier_id) REFERENCES users(id));
CREATE TABLE notifications (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, message VARCHAR(500) NOT NULL, created_at DATETIME NOT NULL, `read` BOOLEAN NOT NULL DEFAULT FALSE, INDEX ix_notification_user(user_id), FOREIGN KEY(user_id) REFERENCES users(id));
